gQQ(){return"\u062f\u062f\u0627\u0646 \u0648\u06d5\u06a9 \u067e\u06cc\u062a\u06ce\u0646 \u0686\u0627\u0631\u06d5\u06a9\u0627\u0646 \u0644 \u0633\u06d5\u0631 \u0686\u0627\u067e\u06a9\u0631\u0646\u0627\u0646 (UL1)"},
gQP(){return"\u0647\u06d5\u0644\u06a9\u0631\u06cc: \u0644\u06ce\u0628\u0644\u06ce\u0646 \u06a9\u06d5\u06cc\u0633\u0627\u0646 \u0648 \u062a\u06a9\u06ce\u062a\u06ce\u0646 \u0648\u06d5\u0631\u06af\u0631\u062a\u0646\u06ce \u062f\u062f\u0627\u0646\u0627\u0646 \u0648\u06d5\u06a9 UL1\u060c UR2\u2026 \u062f\u0646\u06a4\u06cc\u0633\u0646 \u0644 \u062c\u0647\u06ce \u0698\u0645\u0627\u0631\u06ce\u0646 FDI (21\u060c 12\u2026)."},
